const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.chatroom_name) {
    node.error("WaSOS not configured on this connection");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.wasos
    + "/api/chat/messages/" + target.client_specific.chatroom_name;

msg.headers = {
    "x-api-key":    target.api_key,
    "Content-Type": "application/json"
};

return msg;

msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;

/**
 * Append any skipped-file notice to payload.content.
 */
const entry   = msg.entry;
const files   = (entry && entry.files) || [];
const skipped = files.filter(f => f.skipped);

if (skipped.length === 0) return msg;

const total  = files.length;
const notice = " [" + skipped.length + "/" + total
             + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

msg.payload.content = (msg.payload.content || "") + notice;

return msg;
